PRAGMA foreign_keys = ON;
CREATE TABLE organizations (id TEXT PRIMARY KEY CHECK(id IN ('program','ministry')), revision INTEGER NOT NULL DEFAULT 0);
INSERT INTO organizations(id) VALUES ('program'),('ministry');
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT NOT NULL, admin INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, must_change_password INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TRIGGER keep_last_admin BEFORE UPDATE ON users WHEN OLD.admin=1 AND OLD.active=1 AND (NEW.admin=0 OR NEW.active=0) AND (SELECT COUNT(*) FROM users WHERE admin=1 AND active=1)=1 BEGIN SELECT RAISE(ABORT,'LAST_ADMIN'); END;
CREATE TABLE nodes (id TEXT PRIMARY KEY, domain TEXT NOT NULL REFERENCES organizations(id), kind TEXT NOT NULL, code TEXT NOT NULL COLLATE NOCASE, parent_id TEXT REFERENCES nodes(id) ON DELETE RESTRICT, unit_id TEXT REFERENCES nodes(id) ON DELETE RESTRICT, restricted INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(domain,code));
CREATE INDEX nodes_domain ON nodes(domain);
CREATE INDEX nodes_parent ON nodes(parent_id);
CREATE INDEX nodes_unit ON nodes(unit_id);
CREATE TABLE grants (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, domain TEXT NOT NULL REFERENCES organizations(id), role TEXT NOT NULL CHECK(role IN ('admin','performance','strategy','ambassador','department','owner','director','viewer','strategy_head')), unit_id TEXT REFERENCES nodes(id) ON DELETE RESTRICT, restricted INTEGER NOT NULL DEFAULT 0);
CREATE INDEX grants_user ON grants(user_id);
CREATE TABLE links (id TEXT PRIMARY KEY, domain TEXT NOT NULL REFERENCES organizations(id), source_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE RESTRICT, target_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE RESTRICT, UNIQUE(source_id,target_id), CHECK(source_id <> target_id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE audit (id TEXT PRIMARY KEY, domain TEXT, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, before_json TEXT, after_json TEXT, at TEXT NOT NULL);
CREATE INDEX audit_domain_at ON audit(domain, at);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT, 'AUDIT_IMMUTABLE'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT, 'AUDIT_IMMUTABLE'); END;
CREATE TABLE write_guards (id TEXT PRIMARY KEY, ok INTEGER NOT NULL CHECK(ok=1));
CREATE TRIGGER nodes_parent_domain_insert BEFORE INSERT ON nodes WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM nodes WHERE id=NEW.parent_id AND domain=NEW.domain) BEGIN SELECT RAISE(ABORT,'CROSS_DOMAIN'); END;
CREATE TRIGGER nodes_unit_domain_insert BEFORE INSERT ON nodes WHEN NEW.unit_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM nodes WHERE id=NEW.unit_id AND domain=NEW.domain AND kind='unit') BEGIN SELECT RAISE(ABORT,'CROSS_DOMAIN'); END;
CREATE TRIGGER nodes_parent_domain_update BEFORE UPDATE ON nodes WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM nodes WHERE id=NEW.parent_id AND domain=NEW.domain) BEGIN SELECT RAISE(ABORT,'CROSS_DOMAIN'); END;
CREATE TRIGGER nodes_unit_domain_update BEFORE UPDATE ON nodes WHEN NEW.unit_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM nodes WHERE id=NEW.unit_id AND domain=NEW.domain AND kind='unit') BEGIN SELECT RAISE(ABORT,'CROSS_DOMAIN'); END;
CREATE TRIGGER links_domain_insert BEFORE INSERT ON links WHEN NOT EXISTS(SELECT 1 FROM nodes s JOIN nodes t ON t.id=NEW.target_id WHERE s.id=NEW.source_id AND s.domain=NEW.domain AND t.domain=NEW.domain) BEGIN SELECT RAISE(ABORT,'CROSS_DOMAIN'); END;
CREATE TRIGGER grants_domain_insert BEFORE INSERT ON grants WHEN NEW.unit_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM nodes WHERE id=NEW.unit_id AND kind='unit' AND domain=NEW.domain) BEGIN SELECT RAISE(ABORT,'CROSS_DOMAIN'); END;
